import pyomo.environ as pyo

DATA = {
    "cities": [1, 2, 3, 4, 5],
    "cost": {
        (1, 2): 73, (1, 3): 39, (1, 4): 79, (1, 5): 38,
        (2, 1): 73, (2, 3): 30, (2, 4): 46, (2, 5): 29,
        (3, 1): 39, (3, 2): 30, (3, 4): 88, (3, 5): 57,
        (4, 1): 79, (4, 2): 46, (4, 3): 88, (4, 5): 59,
        (5, 1): 38, (5, 2): 29, (5, 3): 57, (5, 4): 59,
    },
    "depot": 1,
    "big_m": 5,
    "order_lb": 2,
    "order_ub": 5,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    cities = d["cities"]
    depot = d["depot"]

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=cities, ordered=True)

    def arcs_rule(m):
        return [(i, j) for i in cities for j in cities if i != j]
    model.A = pyo.Set(dimen=2, initialize=arcs_rule)

    model.NT = pyo.Set(initialize=[i for i in cities if i != depot], ordered=True)

    def cost_rule(m, i, j):
        return d["cost"][(i, j)]
    model.c = pyo.Param(model.A, initialize=cost_rule)

    model.x = pyo.Var(model.A, domain=pyo.Binary)

    model.u = pyo.Var(
        model.NT,
        domain=pyo.NonNegativeReals,
        bounds=(d["order_lb"], d["order_ub"]),
    )

    def obj_rule(m):
        return sum(m.c[i, j] * m.x[i, j] for (i, j) in m.A)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def out_rule(m, i):
        return sum(m.x[i, j] for j in cities if j != i) == 1
    model.out_arc = pyo.Constraint(model.N, rule=out_rule)

    def in_rule(m, j):
        return sum(m.x[i, j] for i in cities if i != j) == 1
    model.in_arc = pyo.Constraint(model.N, rule=in_rule)

    def mtz_rule(m, i, j):
        if i == depot or j == depot:
            return pyo.Constraint.Skip
        return m.u[j] >= m.u[i] + 1 - d["big_m"] * (1 - m.x[i, j])
    model.mtz = pyo.Constraint(model.A, rule=mtz_rule)

    return model
